import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with customer, date and lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
});

test('createInvoice normalizes customerId', () => {
  const result = createInvoice({
    customerId: '  c-003  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice accepts lowercase customerId', () => {
  const result = createInvoice({
    customerId: 'c-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice accepts customerId with spaces', () => {
  const result = createInvoice({
    customerId: ' C-003 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice sets default terms to NET30', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
});

test('createInvoice sets default dueDate for NET30', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2026-10-31');
});

test('createInvoice reports TERMS_INVALID for unknown terms', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'INVALID',
  });
  assert.deepEqual(result, { ok: false, error: 'TERMS_INVALID' });
});

test('invoiceTotals includes voucher in return value', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.ok(totals.voucher !== undefined);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals calculates total with voucher', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const voucherResult = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 });
  const totals = invoiceTotals(voucherResult.value);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, 60000 - 10000);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const result = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'WELCOME10');
  assert.equal(result.value.voucher.amount, 10000);
});

test('applyVoucher reports NOT_DRAFT for issued invoice', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  invoice = issueInvoice(invoice, []).value;
  const result = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher reports VOUCHER_EXISTS if one already applied', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  invoice = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 }).value;
  const result = applyVoucher(invoice, { code: 'LOYALTY5', amount: 5000 });
  assert.deepEqual(result, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher reports AMOUNT_INVALID for zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const result = applyVoucher(invoice, { code: 'WELCOME10', amount: 0 });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher reports AMOUNT_INVALID for negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const result = applyVoucher(invoice, { code: 'WELCOME10', amount: -5000 });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher reports AMOUNT_INVALID for fractional amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const result = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000.5 });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher does not mutate input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const copy = JSON.parse(JSON.stringify(invoice));
  applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 });
  assert.deepEqual(invoice, copy);
});

test('applyVoucher preserves all invoice fields', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
    terms: 'NET14',
  }).value;
  const result = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 });
  assert.equal(result.value.customerId, 'C-002');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.terms, 'NET14');
  assert.ok(result.value.dueDate);
});

test('createInvoice copies name, unitPrice and vatRate from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const line = result.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
